   { "label": "Wikipedia — Cuneiform", "url": "https://en.wikipedia.org/wiki/Cuneiform" },
   { "label": "Wikipedia — Proto-cuneiform", "url": "https://en.wikipedia.org/wiki/Proto-cuneiform" },
   { "label": "Wikipedia — Proto-Elamite script", "url": "https://en.wikipedia.org/wiki/Proto-Elamite_script" },
   { "label": "Schmandt-Besserat, 'The Invention of Tokens' (University of Texas at Austin)", "url": "https://sites.utexas.edu/dsb/tokens/the-invention-of-tokens/" }
